package genhelper

import (
	"encoding/json"
	"fmt"
	"maps"
	"slices"
	"strconv"
	"strings"
)

// GeneratedComment returns the comment marking a file as generated by
// generator, in the form Go tools recognize:
//
//	// Code generated by generator. DO NOT EDIT.
//
// The comment is one section of the header [PrintFileHeader] and
// [WrapFile] take. It must come before the package clause.
func GeneratedComment(generator string) string {
	return "// Code generated by " + generator + ". DO NOT EDIT."
}

// GeneratorParams describes the run of a generator, for the header of the
// files it writes.
type GeneratorParams struct {
	// Name names the generator, usually by its import path.
	Name string
	// Argv holds the command line arguments of the run. It may be empty.
	//
	// The header repeats them, so arguments differing between machines,
	// such as absolute paths, make the generated file differ too.
	Argv []string
	// Params holds the settings of the run that are not arguments. The
	// values must encode as JSON. It may be empty.
	Params map[string]any
}

// Comment returns the header section of g: the comment of
// [GeneratedComment], then the arguments and the parameters.
//
//	// Code generated by name. DO NOT EDIT.
//	// argv: -type T "an argument"
//	// params:
//	//	key: "value"
//
// The parameters are sorted by key and each value is printed as JSON, so
// equal runs give equal text. An argument or a key is quoted where it would
// not read as one word. A line for empty Argv or empty Params is left out.
//
// Comment returns the error of encoding/json for a value JSON does not
// encode.
func (g GeneratorParams) Comment() (string, error) {
	var b strings.Builder
	b.WriteString(GeneratedComment(g.Name))
	if len(g.Argv) > 0 {
		b.WriteString("\n// argv:")
		for _, arg := range g.Argv {
			b.WriteString(" ")
			b.WriteString(word(arg))
		}
	}
	if len(g.Params) > 0 {
		b.WriteString("\n// params:")
		for _, key := range slices.Sorted(maps.Keys(g.Params)) {
			value, err := json.Marshal(g.Params[key])
			if err != nil {
				return "", fmt.Errorf("genhelper: generator parameter %q: %w", key, err)
			}
			fmt.Fprintf(&b, "\n//\t%s: %s", word(key), value)
		}
	}
	return b.String(), nil
}

// word returns s as it is when it reads as one word of a comment line, and
// quoted otherwise. Quoting keeps a line break of s from ending the
// comment.
func word(s string) string {
	quoted := strconv.Quote(s)
	if s == "" || quoted != `"`+s+`"` || strings.ContainsAny(s, " :") {
		return quoted
	}
	return s
}
